"use client"

import { cn } from "cn"
import { CopyIcon, PencilIcon, ShareIcon, TrashIcon } from "lucide-react"

import { Badge } from "@tecton/react/components/badge"
import {
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "@tecton/react/components/dropdown-menu"
import {
  createColumns,
  DataTableRowActions,
} from "@tecton/react/tecton/data-table"
import { Meter } from "@tecton/react/tecton/meter"
import { useLocale } from "@tecton/react/tecton/provider"

import { formatFirstOil, riskLabel, statusMeta } from "../data"
import type { FdaStatus, FieldDevelopmentAlternative } from "../data"

/** An alternative with its rank: its place in the list, ranked by NPV. */
type RankedAlternative = FieldDevelopmentAlternative & { rank: number }

function MonoValue({
  value,
  unit,
  className,
  digits = 1,
  prefix,
}: {
  value: number
  unit?: string
  className?: string
  digits?: number
  prefix?: string
}) {
  const { locale } = useLocale()
  return (
    <span className={cn("font-mono tabular-nums", className)}>
      {prefix}
      {value.toLocaleString(locale, {
        minimumFractionDigits: digits,
        maximumFractionDigits: digits,
      })}
      {unit && (
        <span className="ms-1 text-[0.85em] text-muted-foreground">{unit}</span>
      )}
    </span>
  )
}

type ColumnCallbacks = {
  onOpen?: ((fda: RankedAlternative) => void) | undefined
  onDuplicate?: (fda: RankedAlternative) => void
  onDelete?: (fda: RankedAlternative) => void
}

const statusOptions = (Object.keys(statusMeta) as FdaStatus[]).map(
  (status) => ({
    value: status,
    label: statusMeta[status].label,
    variant: statusMeta[status].color,
  })
)

/** Column definitions for the FDA comparison table. */
function createFdaColumns(callbacks: ColumnCallbacks = {}) {
  return createColumns<RankedAlternative>([
    {
      id: "rank",
      header: "Rank",
      type: "number",
      align: "start",
      rowHeader: false,
      cell: (fda) => (
        <span className="flex items-center gap-2">
          <span
            aria-hidden
            className="h-6 w-1.5 shrink-0 rounded-sm"
            style={{ background: fda.color }}
          />
          <span className="font-mono tabular-nums">{fda.rank}</span>
        </span>
      ),
    },
    {
      id: "code",
      header: "FDA",
      // The FDA names the row, so a screen reader reads it with every cell.
      rowHeader: true,
      cell: (fda) => (
        <span className="flex min-w-0 items-center gap-2">
          <span className="shrink-0 font-mono text-muted-foreground">
            {fda.code}
          </span>
          <span className="truncate font-medium">{fda.name}</span>
        </span>
      ),
    },
    {
      id: "npv",
      header: "NPV",
      type: "number",
      cell: (fda) => (
        <MonoValue
          value={fda.npv}
          prefix="$"
          unit="MM"
          className="text-success"
        />
      ),
    },
    {
      id: "irr",
      header: "IRR",
      type: "number",
      cell: (fda) => <MonoValue value={fda.irr} unit="%" />,
    },
    {
      id: "capex",
      header: "CAPEX",
      type: "number",
      cell: (fda) => <MonoValue value={fda.capex} prefix="$" unit="MM" />,
    },
    {
      id: "peakProduction",
      header: "Peak production",
      type: "number",
      cell: (fda) => <MonoValue value={fda.peakProduction} unit="Mbbl/d" />,
    },
    {
      id: "firstOil",
      header: "First oil",
      // "2029-03": sorts chronologically as text.
      cell: (fda) => (
        <span className="font-mono tabular-nums">
          {formatFirstOil(fda.firstOil)}
        </span>
      ),
    },
    {
      id: "risk",
      header: "Risk",
      type: "number",
      align: "start",
      cell: (fda) => (
        <Meter
          aria-label={`Risk ${riskLabel(fda.risk)}`}
          value={fda.risk}
          color="auto"
          size="sm"
          segments={5}
          valueLabel={
            <span className="text-[0.625rem]">{riskLabel(fda.risk)}</span>
          }
          className="w-28 gap-0.5"
        />
      ),
    },
    {
      id: "status",
      header: "Status",
      type: "options",
      options: statusOptions,
      cell: (fda) => {
        const meta = statusMeta[fda.status]
        return (
          <Badge
            variant={meta.color}
            appearance={fda.status === "archived" ? "outline" : "solid"}
          >
            {meta.label}
          </Badge>
        )
      },
    },
    {
      id: "actions",
      header: "Actions",
      renderHeader: () => <span className="sr-only">Actions</span>,
      align: "end",
      sortable: false,
      hideable: false,
      cell: (fda) => (
        <DataTableRowActions aria-label={`Actions for ${fda.code}`}>
          <DropdownMenuItem onClick={() => callbacks.onOpen?.(fda)}>
            <PencilIcon /> Open
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => callbacks.onDuplicate?.(fda)}>
            <CopyIcon /> Duplicate
          </DropdownMenuItem>
          <DropdownMenuItem>
            <ShareIcon /> Share
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem
            variant="destructive"
            onClick={() => callbacks.onDelete?.(fda)}
          >
            <TrashIcon /> Delete
          </DropdownMenuItem>
        </DataTableRowActions>
      ),
    },
  ])
}

export { createFdaColumns, MonoValue }
export type { ColumnCallbacks, RankedAlternative }

"use client"

import * as React from "react"
import { cn } from "cn"
import { PlusIcon } from "lucide-react"

import { Button } from "@tecton/react/components/button"
import {
  DataTable,
  DataTableActionBar,
  DataTableContent,
} from "@tecton/react/tecton/data-table"

import { createFdaColumns, MonoValue } from "./components/fda-columns"
import type { RankedAlternative } from "./components/fda-columns"
import { alternatives as allAlternatives } from "./data"
import type { FieldDevelopmentAlternative } from "./data"

type FdaComparisonTableProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue"
> & {
  data?: FieldDevelopmentAlternative[]
  onOpen?: (fda: FieldDevelopmentAlternative) => void
  /** Called with the selected alternatives, from the selection's action bar. */
  onAddComparison?: (fdas: FieldDevelopmentAlternative[]) => void
}

/** The alternative as the list keeps it, without its rank. */
function unranked({ rank: _rank, ...fda }: RankedAlternative) {
  return fda
}

/**
 * FDA comparison table — ranked field development alternatives with mono
 * economics, an auto-coloured risk meter, status badges and a row menu, on
 * a compact, striped `DataTable`: a header sorts its column, a row's
 * checkbox selects it, and Enter, a double click or a click while nothing
 * is selected opens it; the row's actions menu opens it too. While rows
 * are selected, an action bar adds them to a comparison.
 */
function FdaComparisonTable({
  className,
  data = allAlternatives,
  onOpen,
  onAddComparison,
  ...props
}: FdaComparisonTableProps) {
  const [rows, setRows] = React.useState(data)
  const [selected, setSelected] = React.useState<ReadonlyArray<string>>([])
  // Copies are numbered by a counter that only grows, so an id is never
  // reused after a row is deleted (the row count would repeat).
  const copies = React.useRef(0)

  // The rank is the alternative's place in the list, whatever the sort.
  const ranked = React.useMemo(
    () => rows.map((fda, index) => ({ ...fda, rank: index + 1 })),
    [rows]
  )

  const columns = React.useMemo(
    () =>
      createFdaColumns({
        onOpen: onOpen && ((fda) => onOpen(unranked(fda))),
        onDuplicate: (fda) => {
          copies.current += 1
          const id = `${fda.id}-copy-${copies.current}`
          setRows((current) => [
            ...current,
            {
              ...unranked(fda),
              id,
              code: `${fda.code} (copy)`,
              status: "screening",
            },
          ])
        },
        onDelete: (fda) =>
          setRows((current) => current.filter((row) => row.id !== fda.id)),
      }),
    [onOpen]
  )

  return (
    <DataTable
      items={ranked}
      columns={columns}
      selectionMode="multiple"
      value={selected}
      onValueChange={setSelected}
      size="sm"
      striped
      {...(onOpen === undefined
        ? {}
        : {
            onActivate: (_: string, fda: RankedAlternative) =>
              onOpen(unranked(fda)),
          })}
      className={cn("w-full", className)}
      {...props}
    >
      <DataTableActionBar aria-label="Selected alternatives">
        <Button
          variant="outline"
          size="sm"
          onClick={() =>
            onAddComparison?.(rows.filter((row) => selected.includes(row.id)))
          }
        >
          <PlusIcon data-icon="inline-start" /> Add comparison
        </Button>
      </DataTableActionBar>
      <DataTableContent
        aria-label="Field development alternatives"
        empty="No alternatives yet."
      />
    </DataTable>
  )
}

/** Route-ready page: the table with a small summary header. */
export default function FdaComparisonTablePage() {
  return (
    <div
      data-slot="fda-comparison-table-page"
      className="flex min-h-svh w-full flex-col gap-4 bg-background px-4 py-8 text-foreground md:px-8"
    >
      <header className="flex flex-col gap-1">
        <h1 className="text-lg font-medium">Field development alternatives</h1>
        <p className="text-sm text-muted-foreground">
          Ranked by NPV. Select two or more rows to compare cost, schedule and
          risk side by side.
        </p>
      </header>
      <FdaComparisonTable />
    </div>
  )
}

export { FdaComparisonTable, createFdaColumns, MonoValue }
export { alternatives, statusMeta, riskLabel, formatFirstOil } from "./data"
export type { FdaComparisonTableProps }
export type { RankedAlternative } from "./components/fda-columns"
export type { FieldDevelopmentAlternative, FdaStatus } from "./data"
